INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63756108', 63756108, 'analyze_legacy', 'Kementerian Ketenagakerjaan', 'central', 'Sekretariat Jenderal', 'Layanan Pengelolaan Media Sosial', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 200000000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'Kegiatan pengelolaan interaksi publik secara aktif, profesional, dan berkesinambungan pada seluruh kanal media sosial resmi Kementerian Ketenagakerjaan (X, Instagram, Youtube, Facebook, dan TikTok), khususnya dalam hal pemantauan, moderasi, serta penanganan komentar dan pesan langsung (direct message) dari masyarakat. Ruang lingkup pekerjaan mencakup menjawab pertanyaan, keluhan, aspirasi, dan umpan balik publik secara cepat, akurat, santun, dan sesuai dengan kebijakan serta ketentuan peraturan perundang-undangan yang berlaku menggunakan satu aplikasi yang terintegrasi antar semua medsos Kemnaker, dengan mengedepankan prinsip pelayanan informasi publik, komunikasi yang humanis, dan perlindungan reputasi institusi. Kegiatan ini juga mencakup pengelompokan isu, eskalasi isu strategis atau sensitif kepada unit terkait, dokumentasi interaksi publik, serta pelaporan berkala sebagai bahan evaluasi dan pengambilan kebijakan komunikasi publik Kementerian Ketenagakerjaan.', '1. Cakupan Kanal Media Sosial Pengelolaan interaksi publik dilakukan pada seluruh kanal media sosial resmi Kementerian Ketenagakerjaan, meliputi X (Twitter), Instagram, YouTube, Facebook, dan TikTok. 2. Pemantauan dan Moderasi Interaksi Melaksanakan pemantauan real-time terhadap komentar, balasan, mention, dan pesan langsung (direct message), termasuk moderasi konten negatif, spam, ujaran kebencian, hoaks, dan pelanggaran etika komunikasi publik sesuai pedoman yang ditetapkan. 3. Penanganan dan Respons Publik Memberikan respons terhadap pertanyaan, keluhan, aspirasi, dan umpan balik masyarakat secara cepat, akurat, informatif, santun, dan konsisten dengan kebijakan pemerintah serta ketentuan peraturan perundang-undangan di bidang ketenagakerjaan dan keterbukaan informasi publik. 4. Penggunaan Aplikasi Terintegrasi Seluruh aktivitas pengelolaan interaksi dilakukan melalui satu aplikasi manajemen media sosial yang terintegrasi untuk seluruh kanal, yang memiliki kemampuan pemantauan lintas platform, manajemen percakapan, pencatatan respons, dan pelacakan riwayat interaksi. 5. Eskalasi Isu Strategis Melaksanakan mekanisme eskalasi terhadap isu strategis, sensitif, atau berpotensi krisis kepada unit kerja terkait secara berjenjang dan terdokumentasi, untuk memastikan keselarasan substansi jawaban dan mitigasi risiko reputasi. 6. Dokumentasi dan Arsip Interaksi Menyusun dan menyimpan dokumentasi digital seluruh interaksi publik sebagai arsip komunikasi resmi, termasuk kronologi percakapan, jenis isu, waktu respons, dan tindak lanjut yang dilakukan. 7. Pelaporan Berkala Menyediakan laporan berkala (bulanan dan/atau sesuai kebutuhan) yang memuat statistik interaksi, jenis dan tren isu, kecepatan respons, isu dominan, serta rekomendasi perbaikan sebagai bahan evaluasi dan pengambilan kebijakan komunikasi publik Kementerian Ketenagakerjaan. 8. Standar Layanan dan Etika Komunikasi Seluruh pelaksanaan pekerjaan wajib mengedepankan prinsip pelayanan informasi publik, komunikasi yang humanis dan inklusif, akuntabilitas, serta perlindungan reputasi institusi pemerintah.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1128749);
